1	// src/lib/plattform/backend/kyc.js
2	//
3	// Backend-Teil „KYC/KYB – Identitäts- und Firmenprüfung“ (eigene Schnittstelle, backend/index.js bleibt unverändert).
4	// Gleiche Auswahl wie backend(): Frappe bei PLATTFORM_BACKEND=frappe, sonst Demo (503 im Produktions-Build ohne PLATTFORM_DEMO=1).
5	//
6	// Operationen (n = angemeldeter Nutzer), Vertrag: docs/API.md Abschnitt 11:
7	//   Nutzer:      kycFall(n) · kycSpeichern(n,{abschnitt,daten}) · kycDokumentSpeichern(n,{art,flaecheId,personId,ausgestelltAm,name,mime,daten})
8	//                kycDokumentLesen(n,id,{ip}) → {meta,daten} · kycDokumentLoeschen(n,id) · kycEinreichen(n,{ip}) · kycErneut(n)
9	//   Querschnitt: kycStatus(n|null,{kontoId|organisationId}) · kycFreigabePruefen(n,{schritt,kontoId,organisationId,flaecheId})
10	//   Compliance:  kycWarteschlange(n,{status,q}) · kycFallDetail(n,id,{ip}) · kycAktion(n,id,{aktion,…}) · kycEinstellungen(n)
11	//                kycEinstellungenSpeichern(n,daten) · kycSanktionsliste(n) · kycSanktionPruefen(n,{name,geburtsdatum,art}) · kycFristen(n,{stichtag})
12	//
13	// FÜR ANDERE TEAMS (serverseitig):
14	//   import { kycStatus, kycFreigabe } from "@/lib/plattform/backend/kyc";
15	//   const s = await kycStatus(nutzer);                      // bzw. kycStatus({ organisationId }) / kycStatus("U-26-…")
16	//   const f = await kycFreigabe("auszahlung", { kontoId, flaecheId });   // { ok, aktiv, gruende, hinweis }
17	//   Im Demo-Backend innerhalb einer Schreib-Transaktion: kycSperre(db, schritt, {kontoId,…}) aus backend/demo/kycRegeln.js.
18	//   Frappe: oekoinvest_app.plattform.kyc_kern.kyc_status(konto) bzw. kyc_sperre(schritt, konto_id=…, …).
19	//
20	// Nur serverseitig verwenden.
21	
22	import * as demo from "./demo/kyc";
23	import * as frappe from "./frappe/kyc";
24	import { backendName, KONFIG_FEHLER } from "./index";
25	import { PlattformFehler } from "../fehler";
26	
27	export const KYC_OPERATIONEN = [
28	  "kycFall", "kycSpeichern", "kycDokumentSpeichern", "kycDokumentLesen", "kycDokumentLoeschen", "kycEinreichen", "kycErneut", "kycStatus",
29	  "kycFreigabePruefen", "kycWarteschlange", "kycFallDetail", "kycAktion", "kycEinstellungen", "kycEinstellungenSpeichern", "kycSanktionsliste",
30	  "kycSanktionPruefen", "kycFristen", "kycFreigabeSystem",
31	];
32	
33	if (process.env.NODE_ENV !== "production") {
34	  for (const [name, impl] of [["demo", demo], ["frappe", frappe]]) {
35	    const fehlt = KYC_OPERATIONEN.filter((op) => typeof impl[op] !== "function");
36	    if (fehlt.length) console.warn(`[plattform] KYC ${name}: fehlende Operationen ${fehlt.join(", ")}`);
37	  }
38	}
39	
40	export function kycBackend() {
41	  const n = backendName();
42	  if (n === "frappe") return frappe;
43	  if (n === "demo") return demo;
44	  throw new PlattformFehler(503, KONFIG_FEHLER);
45	}
46	
47	/**
48	 * KYC-Status eines Kontos oder einer Organisation (Systemaufruf ohne Nutzerkontext, nur serverseitig).
49	 * ziel: Nutzer-Objekt ({ id }) · Organisation ({ id, art } oder { organisationId }) · Kennung "U-…"/"O-…"
50	 * Liefert { status, verifiziert, kontotyp, fallId, bank: { vorhanden, geprueft }, eigentum: [flaecheIds], naechstePruefung, … }
51	 */
52	export async function kycStatus(ziel) {
53	  let kontoId = null;
54	  let organisationId = null;
55	  if (typeof ziel === "string") (ziel.startsWith("O-") ? (organisationId = ziel) : (kontoId = ziel));
56	  else if (ziel?.organisationId) organisationId = ziel.organisationId;
57	  else if (ziel?.rollen || ziel?.email) {
58	    kontoId = ziel.id;
59	    organisationId = ziel.organisation?.id || null;
60	  } else if (ziel?.id?.startsWith?.("O-")) organisationId = ziel.id;
61	  else kontoId = ziel?.id || null;
62	  return kycBackend().kycStatus(null, { kontoId, organisationId });
63	}
64	
65	/** Freigabe eines Schritts (Gating) als Systemaufruf: { ok, aktiv, gruende, hinweis } */
66	export async function kycFreigabe(schritt, { kontoId = null, organisationId = null, flaecheId = null } = {}) {
67	  return kycBackend().kycFreigabeSystem(schritt, { kontoId, organisationId, flaecheId });
68	}
