285	export function ibanNormalisieren(s) {
286	  return String(s || "").toUpperCase().replace(/[\s-]/g, "");
287	}
288	
289	/** Prüfziffer nach ISO 13616 (mod 97 = 1) und Länge je Land. Liefert { ok, iban, land, fehler } */
290	export function ibanPruefen(eingabe) {
291	  const iban = ibanNormalisieren(eingabe);
292	  if (!iban) return { ok: false, iban: "", land: "", fehler: "Bitte geben Sie eine IBAN an." };
