473	export function kycRisiko(fall, einstellungen = kycEinstellungenStandard()) {
474	  const f = fall || {};
475	  const hoch = new Set((einstellungen.hochrisikoLaender || []).map((x) => String(x).toUpperCase()));
476	  const gruende = [];
477	  let punkte = 0;
478	  const plus = (n, g) => {
479	    punkte += n;
480	    gruende.push(g);
481	  };
482	  const dach = ["DE", "AT", "CH", "LI"];
483	  const eu = ["BE", "BG", "CY", "CZ", "DK", "EE", "ES", "FI", "FR", "GR", "HR", "HU", "IE", "IT", "LT", "LU", "LV", "MT", "NL", "PL", "PT", "RO", "SE", "SI", "SK", "IS", "NO"];
484	  const laender = [f.person?.adresse?.land, f.person?.staatsangehoerigkeit, f.firma?.land, ...(f.ubos || []).map((u) => u.wohnsitzland)].filter(Boolean).map((x) => String(x).toUpperCase());
485	  if (laender.some((l) => hoch.has(l))) plus(4, "Bezug zu einem Drittland mit hohem Risiko");
486	  else if (laender.some((l) => !dach.includes(l) && !eu.includes(l))) plus(2, "Bezug außerhalb EU/EWR/Schweiz");
487	  else if (laender.some((l) => !dach.includes(l))) plus(1, "Bezug zu einem EU/EWR-Land außerhalb DACH");
