495	    if (f.firma?.treuhand) plus(2, "Treuhand-/Stiftungsstruktur");
496	  }
497	  const betrag = KYC_TICKETS[f.mittelherkunft?.ticket]?.betrag || 0;
498	  if (betrag > 5000000) plus(2, "Ticketgröße über 5 Mio. €");
499	  else if (betrag > 1000000) plus(1, "Ticketgröße über 1 Mio. €");
500	  if (f.sanktionen?.status === "treffer_pruefen" || f.sanktionen?.status === "bestaetigt") plus(4, "Möglicher Treffer im Sanktionslisten-Abgleich");
