      geburtsdatumRoh: b.slice(0, 6), geschlecht: b[7], ablaufRoh: b.slice(8, 14), staatsangehoerigkeit: b.slice(15, 18),
      optional: fueller(optional1 + b.slice(18, 29)), ...nameTeilen(c),
    };
