  }

  f.dokumentart = DOKUMENTART[f.dokumentcode[0]] || "Reisedokument";
  f.ausstellerstaat = f.ausstellerstaat.replace(/</g, "");
  f.staatsangehoerigkeit = f.staatsangehoerigkeit.replace(/</g, "");
  f.geschlecht = f.geschlecht === "<" ? "X" : f.geschlecht;
