      ...((f.gesellschafter || []).length ? [{ titel: "Gesellschafter", tabelle: { kopf: ["Name", "Anteil"], zeilen: f.gesellschafter.map((g) => [g.name, g.anteil != null ? `${g.anteil} %` : ""]) } }] : []),
