          {live && (
            <div aria-live="polite" className="rounded-2xl bg-ink-50 px-4 py-3 text-[13px]">
              <p className="font-semibold text-ink-900">{live.format ? `Format ${live.format} · ${live.felder.dokumentart}` : "Format nicht erkannt"}</p>
