  });
  const Hges = oben + reihen.length * DY + 12;
  const externZu = new Map();
  for (const x of extern) (externZu.get(x.nach) || externZu.set(x.nach, []).get(x.nach)).push(x);

  return (
    <div className="overflow-x-auto">
