            {schritt < SCHRITTE.length - 1 && <Button type="button" size="sm" variant="navy" onClick={() => setSchritt((s) => s + 1)}>Weiter <ArrowRight aria-hidden="true" className="h-4 w-4" /></Button>}
          </div>
        </div>
      </Karte>
    </div>
  );
}

