def _fristen_melden(n=None):
	heute, in14 = nowdate(), str(add_days(nowdate(), 14))
	gemeldet = 0
	roh = frappe.db.get_default("oekoinvest_gesellschaft_fristen_gemeldet")
	bereits = set(_json(roh, []) or [])
	empfaenger = []
	for k in frappe.get_all("Plattform Konto", filters={"aktiv": 1}, fields=["name"], limit_page_length=0):
		kn = frappe._dict(id=k.name, rollen=[r.rolle for r in frappe.get_all("Plattform Konto Rolle", filters={"parent": k.name}, fields=["rolle"])], backofficeRollen=frappe.db.get_value("Plattform Konto", k.name, "backoffice_rollen"))
		if ist_admin(kn) and stufe(kn, "gesellschaften") >= 2:
			empfaenger.append(k.name)
	for name in frappe.get_all(DT_GES, filters={"status": ("!=", "aufgeloest")}, pluck="name"):
		g = frappe.get_doc(DT_GES, name)
		for f in _ges_json(g)["fristen"]:
