import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const [email, breite, ...ziele] = process.argv.slice(2);
const b = await chromium.launch();
try {
  const ctx = await b.newContext({ viewport: { width: +breite, height: +breite < 600 ? 844 : 900 }, deviceScaleFactor: 1 });
  const login = await ctx.request.post("http://localhost:3100/api/auth/login", { data: { email, passwort: "Demo-2026!" }, headers: { Origin: "http://localhost:3100" }, timeout: 180000 });
  console.log("login", login.status());
  for (const z of ziele) {
    const i = z.indexOf(":");
    const name = z.slice(0, i), pfad = z.slice(i + 1);
    const p = await ctx.newPage();
    const fehler = [];
    p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
    p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 300)));
    const r = await p.goto("http://localhost:3100" + pfad, { waitUntil: "load", timeout: 180000 });
    await p.waitForTimeout(4000);
    const ueber = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
    await p.screenshot({ path: fileURLToPath(new URL(`./shots/ent_${name}_${breite}.png`, import.meta.url)), fullPage: true });
    console.log(r.status(), name, "Überlauf", ueber, fehler.length ? "\n" + fehler.join("\n") : "");
    await p.close();
  }
} finally {
  await b.close();
}

